<script setup>
import {computed,ref} from 'vue';
import {cast} from '../../data/playroom.js';
import {newComic,validateComic,comicScenes,wrapComicText} from '../../room/creativeTools.js';
import {useLocalDraft} from '../../composables/useLocalDraft.js';
import {useStageEditor} from '../../composables/useStageEditor.js';
import {downloadStage} from '../../room/exportImage.js';
import {recordActivity} from '../../room/activityLog.js';
const {state,saved}=useLocalDraft('hitori-room:comic:v1',newComic(),validateComic),svg=ref(null),panelIndex=ref(0),groups=ref([]),message=ref('选中一格，再拖动角色、调整场景，写下这一刻的话。');
const panel=computed(()=>state.value.panels[panelIndex.value]),objects=computed(()=>panel.value.objects),group=computed(()=>groups.value[panelIndex.value]),editor=useStageEditor(group,objects,{width:600,height:360,minY:190,maxY:325});
const selected=computed(()=>objects.value.find(o=>o.key===editor.selectedKey.value));
const asset=path=>`${import.meta.env.BASE_URL}${path}`,person=id=>cast.find(m=>m.id===id),scene=id=>comicScenes.find(s=>s.id===id);
const dimensions=computed(()=>state.value.layout==='grid'?{w:1260,h:870}:{w:640,h:1670});
function placement(i){return state.value.layout==='grid'?`translate(${20+i%2*620},${80+Math.floor(i/2)*380})`:`translate(20,${80+i*390})`;}
function add(id){if(objects.value.length>=4){message.value='每格最多四位角色，先移走一位再邀请新的伙伴。';return;}objects.value.push({key:`cast-${Date.now()}`,id,x:300,y:270,scale:1});editor.selectedKey.value=objects.value.at(-1).key;}
async function exportComic(){try{await downloadStage(svg.value,'hitori-four-panels.png',{scale:1});recordActivity('comic',state.value.title);message.value='四格漫画已导出。';}catch{message.value='导出没能完成，请再试一次。';}}
</script>
<template><section class="room-panel" aria-labelledby="comic-title"><div class="pg-heading"><div><p class="pg-kicker">FOUR LITTLE PANELS / 四コマの、その先</p><h2 id="comic-title">四个画面，装下今天的小故事。</h2><p class="room-intro">选择一格，拖动角色，写上旁白与对白。角色也支持方向键移动，Shift 加快。</p></div><span class="pg-number">18</span></div><div class="pg-toolbar"><label>标题 <input v-model="state.title" maxlength="40"></label><label>版式 <select id="comic-layout" v-model="state.layout" aria-label="版式"><option value="grid">两列四格</option><option value="vertical">竖向四格</option></select></label><button id="comic-export" class="primary" @click="exportComic">导出整张漫画 PNG</button></div><div class="comic-workspace"><div class="pg-board comic-preview"><svg ref="svg" :viewBox="`0 0 ${dimensions.w} ${dimensions.h}`" role="img" aria-label="四格漫画画布" @pointermove="editor.move" @pointerup="editor.up" @pointercancel="editor.up"><rect :width="dimensions.w" :height="dimensions.h" fill="#f4e9d9"/><text :x="dimensions.w/2" y="49" text-anchor="middle" fill="#5a3d57" font-size="27">{{state.title}}</text><g v-for="(p,i) in state.panels" :key="i" :ref="el=>groups[i]=el" :transform="placement(i)" @pointerdown="panelIndex=i"><rect width="600" height="360" :fill="scene(p.scene).background" stroke="#82647a" stroke-width="2"/><path v-if="p.scene==='street'" d="M0 220V120H130V80H280V170H400V100H600V360H0Z" fill="#a2b9b0"/><path v-if="p.scene==='stage'" d="M0 45Q150 130 300 45Q450 130 600 45V0H0Z" fill="#755770"/><rect y="285" width="600" height="75" :fill="scene(p.scene).floor"/><g v-for="o in p.objects" :key="o.key" :transform="`translate(${o.x},${o.y}) scale(${o.scale})`" role="button" tabindex="0" :aria-label="`${person(o.id).name}，可拖动或方向键移动`" class="comic-character" @pointerdown.stop="panelIndex=i;editor.down($event,o)" @keydown="panelIndex=i;editor.key($event,o)"><image :href="asset(person(o.id).image)" x="-53" y="-130" width="106" height="145"/><rect v-if="panelIndex===i&&editor.selectedKey.value===o.key" data-editor-only x="-55" y="-132" width="110" height="150" fill="none" stroke="#9c638e" stroke-dasharray="6 5" stroke-width="3"/></g><g v-if="p.dialogue"><rect x="35" y="49" width="530" :height="35+wrapComicText(p.dialogue).length*24" rx="22" fill="#fcf6e9" stroke="#b697aa"/><path d="M105 90L120 135 140 90" fill="#fcf6e9"/><text x="60" y="80" fill="#5d4558" font-size="21"><tspan v-for="(line,j) in wrapComicText(p.dialogue)" :key="j" x="60" :dy="j?24:0">{{line}}</tspan></text></g><rect width="600" height="36" fill="#f2e5d8" opacity=".95"/><text x="15" y="25" fill="#705267" font-size="20">{{i+1}} / {{p.caption}}</text><rect v-if="panelIndex===i" data-editor-only x="3" y="3" width="594" height="354" fill="none" stroke="#ad7195" stroke-width="6" pointer-events="none"/></g></svg></div><div class="pg-settings"><div class="pg-toolbar"><button v-for="i in 4" :key="i" :aria-pressed="panelIndex===i-1" @click="panelIndex=i-1;editor.selectedKey.value=''">第 {{i}} 格</button></div><label>这一格的场景<select v-model="panel.scene"><option v-for="s in comicScenes" :key="s.id" :value="s.id">{{s.label}}</option></select></label><label>旁白<input v-model="panel.caption" maxlength="40"></label><label>对白（{{panel.dialogue.length}} / 60）<textarea v-model="panel.dialogue" maxlength="60" rows="3"></textarea></label><p class="pg-small">邀请一位角色（每格最多四位）</p><div class="pg-toolbar"><button v-for="m in cast" :key="m.id" @click="add(m.id)">{{m.name}}</button></div><label>选中角色<select :value="editor.selectedKey.value" @change="editor.selectedKey.value=$event.target.value"><option value="">请选择</option><option v-for="o in objects" :key="o.key" :value="o.key">{{person(o.id).name}}</option></select></label><template v-if="selected"><label>横向位置<input v-model.number="selected.x" type="range" min="35" max="565"></label><label>上下位置<input v-model.number="selected.y" type="range" min="190" max="325"></label><label>角色大小<input v-model.number="selected.scale" type="range" min=".6" max="1.5" step=".05"></label><button @click="editor.remove">移走这位角色</button></template><button @click="state=newComic();editor.selectedKey.value=''">恢复最初的四格</button></div></div><p class="pg-status" role="status">{{message}}</p><p class="pg-small">{{saved?'四格内容自动保存在本机。':'本机存档暂不可用。'}} 导出的图片会移除选择框。</p></section></template>
<style scoped>.comic-workspace{display:grid;grid-template-columns:minmax(0,1.7fr) minmax(200px,1fr);gap:22px}.comic-preview{background:#f4e9d9;align-self:start}.comic-character{cursor:grab;touch-action:none}.comic-character:focus-visible{outline:none;filter:drop-shadow(0 0 4px #713957)}.pg-toolbar label{font-size:12px}.pg-toolbar input{max-width:220px}.pg-settings p{margin-bottom:-8px}@media(max-width:850px){.comic-workspace{grid-template-columns:1fr}}</style>
